import os
from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    """Return 0 for even x and 1 for odd x."""
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity of each element of xs, computed in parallel.

    The result is in input order and does not depend on the worker count.
    """
    workers = os.cpu_count() or 1
    return parities_with_workers(xs, workers)


def parities_with_workers(xs: list[int], workers: int) -> list[int]:
    """Return the parity of each element of xs using a thread pool of `workers` threads.

    Raises ValueError if workers < 1. The result is in input order.
    """
    if workers < 1:
        raise ValueError("workers must be at least 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return list(pool.map(parity, xs))


def test_parity_basic() -> None:
    assert parity(0) == 0
    assert parity(1) == 1
    assert parity(4) == 0
    assert parity(7) == 1


def test_parity_negative() -> None:
    assert parity(-1) == 1
    assert parity(-2) == 0


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([5]) == [1]
    assert parities([6]) == [0]


def test_parities_order_preserved() -> None:
    xs = [3, 2, 1, 0, -1, -2, 10, 11]
    assert parities(xs) == [1, 0, 1, 0, 1, 0, 0, 1]


def test_parities_large_input_in_order() -> None:
    xs = list(range(10_000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_matches_sequential_reference() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(2_000)]
    assert parities(xs) == [parity(x) for x in xs]


@pytest.mark.parametrize("workers", [1, 2, 3, 8, 32])
def test_parities_independent_of_worker_count(workers: int) -> None:
    xs = [(i * 31) % 97 - 40 for i in range(500)]
    expected = [parity(x) for x in xs]
    assert parities_with_workers(xs, workers) == expected


def test_parities_with_workers_rejects_zero() -> None:
    with pytest.raises(ValueError):
        parities_with_workers([1, 2], 0)


def test_parities_repeatable() -> None:
    xs = list(range(-50, 50))
    first = parities(xs)
    for _ in range(5):
        assert parities(xs) == first
